1	package govflow
2	
3	import (
4		"encoding/json"
5		"path/filepath"
6		"reflect"
7		"strings"
8		"sync"
9		"testing"
10	)
11	
12	// 本文件为“多个独立命令进程同时创建同编号投票提案”补充回归保障，保护
13	// “一个编号只保存一份完整定义”的既有规则：无论哪个请求先完成，结果都必须
14	// 与按某种先后顺序串行完成一致——不能多个请求都声称首次创建成功，也不能
15	// 由后提交者覆盖已有定义。串行化由进程内互斥锁与 flock 共同保证，
16	// 因此这些用例直接启动多个 CLI 进程压跨进程路径。
17	
18	// createVoteCLIResponse 是 create-vote --json 的成功结果：既有提案对象与
19	// already_exists 标志都必须保留，冲突不得被包装成一次成功重试。
20	type createVoteCLIResponse struct {
21		Proposal *VoteProposalView `json:"proposal"`
22		Existed  bool              `json:"already_exists"`
23	}
24	
25	// createConcResult 记录一个并发创建进程的全部可观察结果。
26	type createConcResult struct {
27		group       string // 仅动作次序冲突用例使用："A" / "B"
28		code        int
29		stdout      string
30		stderr      string
31		memberOrder []string // 该请求自己提交的成员编号顺序
32		resp        *createVoteCLIResponse
33	}
34	
35	// concCreateRoster 与 concMemberExpectations 描述两个用例共用的名单：
36	// alice、bob、carol、dave，原始权重 300/200/100/400，总权重 1000；
37	// 委托 bob -> carol -> alice 是一条经过两次转交的链，查询时必须展示完整
38	// 路径（含中间成员 carol）与正确的最终代表，不能因输入排列不同而漏掉 carol。
39	var concCreateRoster = []string{"alice:300", "bob:200", "carol:100", "dave:400"}
40	
41	type concMemberExpectation struct {
42		weight   int64
43		path     []string
44		delegate string // 最终代表
45		direct   string // 直接委托对象；未委托为空串
46	}
47	
48	var concMemberExpectations = map[string]concMemberExpectation{
49		"alice": {weight: 300, path: []string{"alice"}, delegate: "alice"},
50		"bob":   {weight: 200, path: []string{"bob", "carol", "alice"}, delegate: "alice", direct: "carol"},
51		"carol": {weight: 100, path: []string{"carol", "alice"}, delegate: "alice", direct: "alice"},
52		"dave":  {weight: 400, path: []string{"dave"}, delegate: "dave"},
53	}
54	
55	// concMemberPerm 生成确定性的成员排列：旋转与反向旋转交替，使并发请求采用
56	// 互不相同的成员排列；排列只影响展示顺序，不影响内容相等性。
57	func concMemberPerm(i int) []string {
58		n := len(concCreateRoster)
59		out := make([]string, n)
60		for j := range concCreateRoster {
61			out[j] = concCreateRoster[(j+i)%n]
62		}
63		if i%2 == 1 {
64			for j, k := 0, n-1; j < k; j, k = j+1, k-1 {
65				out[j], out[k] = out[k], out[j]
66			}
67		}
68		return out
69	}
70	
71	// concDelegationPerm 让委托参数也采用不同排列先后：两条委托的输入次序
72	// 不影响同一项委托关系的含义。
73	func concDelegationPerm(i int) []string {
74		d := []string{"bob:carol", "carol:alice"}
75		if i%2 == 0 {
76			return []string{d[1], d[0]}
77		}
78		return d
79	}
80	
81	func concMemberIDs(members []string) []string {
82		ids := make([]string, len(members))
83		for i, m := range members {
84			ids[i] = m[:strings.LastIndex(m, ":")]
85		}
86		return ids
87	}
88	
89	// concCreateVoteArgs 构造一次 create-vote --json 调用的完整参数。
90	// 治理规则在两个用例间固定：quorum=600、voting=[100,200)、timelock=300。
91	func concCreateVoteArgs(id string, members, delegates, actions []string) []string {
92		args := []string{"create-vote", "--id", id}
93		for _, m := range members {
94			args = append(args, "--member", m)
95		}
96		for _, d := range delegates {
97			args = append(args, "--delegate", d)
98		}
99		args = append(args, "--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300")
100		for _, a := range actions {
101			args = append(args, "--action", a)
102		}
103		return append(args, "--json")
104	}
105	
106	// runConcurrentCreates 用同一个启动栅栏同时放出 n 个独立创建进程，
107	// 每个进程采用不同的成员排列与委托排列，动作由 actionsFor(i) 决定。
108	func runConcurrentCreates(t *testing.T, binary, state, id string, n int, actionsFor func(i int) []string) []createConcResult {
109		t.Helper()
110		results := make([]createConcResult, n)
111		var wg sync.WaitGroup
112		start := make(chan struct{})
113		for i := 0; i < n; i++ {
114			wg.Add(1)
115			go func(i int) {
116				defer wg.Done()
117				members := concMemberPerm(i)
118				args := concCreateVoteArgs(id, members, concDelegationPerm(i), actionsFor(i))
119				<-start
120				so, se, code := runCLI(t, binary, state, args...)
121				results[i] = createConcResult{
122					code:        code,
123					stdout:      so,
124					stderr:      se,
125					memberOrder: concMemberIDs(members),
126				}
127			}(i)
128		}
129		close(start)
130		wg.Wait()
131		return results
132	}
133	
134	// assertSavedConcProposal 核对胜出的保存版本：仍在投票状态、票据为空且无计票
135	// 结论；成员编号与原始权重、委托关系（含两次转交的完整路径与最终代表）、
136	// 法定人数、投票窗口、时间锁、总权重与有序动作全部符合本次共同提交的定义。
137	// wantMemberOrder 非空时还要求成员展示次序就是该顺序（首次创建者的排列）。
138	func assertSavedConcProposal(t *testing.T, v *VoteProposalView, id string, wantActions, wantMemberOrder []string) {
139		t.Helper()
140		if v == nil {
141			t.Fatal("saved proposal view is nil")
142		}
143		if v.ID != id || v.Source != "vote" || v.State != "voting" {
144			t.Fatalf("saved proposal id=%q source=%q state=%q, want %q/vote/voting", v.ID, v.Source, v.State, id)
145		}
146		if v.Quorum != 600 || v.StartAt != 100 || v.Deadline != 200 || v.TimelockEnd != 300 {
147			t.Fatalf("governance rules changed: quorum=%d window=[%d,%d) timelock=%d",
148				v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd)
149		}
150		if v.TotalWeight != 1000 {
151			t.Fatalf("total_weight=%d, want 1000", v.TotalWeight)
152		}
153		if !reflect.DeepEqual(v.Actions, wantActions) {
154			t.Fatalf("actions=%v, want %v in order", v.Actions, wantActions)
155		}
156		if len(v.Ballots) != 0 {
157			t.Fatalf("fresh voting proposal must have empty ballots, got %d: %+v", len(v.Ballots), v.Ballots)
158		}
159		if v.Tally != nil {
160			t.Fatalf("fresh voting proposal must have no tally conclusion, got %+v", v.Tally)
161		}
162		if len(v.Members) != len(concMemberExpectations) {
163			t.Fatalf("member count=%d, want %d", len(v.Members), len(concMemberExpectations))
164		}
165		gotOrder := make([]string, 0, len(v.Members))
166		for _, m := range v.Members {
167			gotOrder = append(gotOrder, m.ID)
168			want, ok := concMemberExpectations[m.ID]
169			if !ok {
170				t.Fatalf("unexpected member %q in saved proposal", m.ID)
171			}
172			if m.Weight != want.weight {
173				t.Fatalf("member %s weight=%d, want %d", m.ID, m.Weight, want.weight)
174			}
175			if m.Delegate != want.delegate {
176				t.Fatalf("member %s final representative=%q, want %q", m.ID, m.Delegate, want.delegate)
177			}
178			if m.Direct != want.direct {
179				t.Fatalf("member %s direct_to=%q, want %q", m.ID, m.Direct, want.direct)
180			}
181			if !reflect.DeepEqual(m.Path, want.path) {
182				t.Fatalf("member %s delegation path=%v, want %v (intermediate hop must not be lost)",
183					m.ID, m.Path, want.path)
184			}
185		}
186		if wantMemberOrder != nil && !reflect.DeepEqual(gotOrder, wantMemberOrder) {
187			t.Fatalf("member display order=%v, must preserve first creator's order %v; reordered retries must not rewrite it",
188				gotOrder, wantMemberOrder)
189		}
190	}
191	
192	// assertNoTreasuryChange 核对创建并发结束后资金库余额、账户余额与执行凭据
193	// 全部保持创建前的值：创建只登记提案，绝不转账、不产生凭据。
194	func assertNoTreasuryChange(t *testing.T, binary, state string, initial int64) {
195		t.Helper()
196		bo, be, code := runCLI(t, binary, state, "balances", "--json")
197		if code != 0 {
198			t.Fatalf("balances query failed: %s", be)
199		}
200		var bal struct {
201			Treasury int64            `json:"treasury"`
202			Balances map[string]int64 `json:"balances"`
203		}
204		if err := json.Unmarshal([]byte(bo), &bal); err != nil {
205			t.Fatalf("balances output is not JSON: %v\n%s", err, bo)
206		}
207		if bal.Treasury != initial {
208			t.Fatalf("treasury balance=%d, must stay %d", bal.Treasury, initial)
209		}
210		if len(bal.Balances) != 0 {
211			t.Fatalf("no transfers may happen at create time, got balances %v", bal.Balances)
212		}
213		ro, re, code := runCLI(t, binary, state, "receipts", "--json")
214		if code != 0 {
215			t.Fatalf("receipts query failed: %s", re)
216		}
217		var receipts []json.RawMessage
218		if err := json.Unmarshal([]byte(ro), &receipts); err != nil {
219			t.Fatalf("receipts output is not JSON: %v\n%s", err, ro)
220		}
221		if len(receipts) != 0 {
222			t.Fatalf("create must produce no execution receipts, got %d", len(receipts))
223		}
224	}
225	
226	// TestCrossProcessConcurrentCreateVoteIdentical：多个进程同时创建同一编号、
227	// 语义完全相同（成员编号与原始权重、委托关系、法定人数、投票窗口、时间锁、
228	// 有序动作一致）但成员排列与委托排列不同的投票提案。所有请求都必须成功，
229	// 其中恰好一个表示首次创建，其余表示已经存在；所有成功返回对应同一份保存
230	// 提案，成员展示次序保留首次成功请求的排列，换序重试不得改写。
231	func TestCrossProcessConcurrentCreateVoteIdentical(t *testing.T) {
232		binary := buildCLI(t)
233		state := filepath.Join(t.TempDir(), "treasury.json")
234		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
235			t.Fatal("init failed")
236		}
237	
238		const id = "gip-conc-create"
239		wantActions := []string{"transfer:audits:100", "transfer:legal:50"}
240		const n = 12
241		results := runConcurrentCreates(t, binary, state, id, n, func(int) []string { return wantActions })
242	
243		firstCreators := 0
244		var winnerView *VoteProposalView
245		var winnerMemberOrder []string
246		for i := range results {
247			r := &results[i]
248			if r.code != 0 {
249				t.Fatalf("process %d failed although content is identical: exit=%d stderr=%s", i, r.code, r.stderr)
250			}
251			r.resp = &createVoteCLIResponse{}
252			if err := json.Unmarshal([]byte(r.stdout), r.resp); err != nil {
253				t.Fatalf("process %d success output is not JSON: %v\n%s", i, err, r.stdout)
254			}
255			if r.resp.Proposal == nil {
256				t.Fatalf("process %d success output missing proposal object: %s", i, r.stdout)
257			}
258			if !r.resp.Existed {
259				firstCreators++
260				winnerView = r.resp.Proposal
261				winnerMemberOrder = r.memberOrder
262			}
263		}
264		if firstCreators != 1 {
265			t.Fatalf("exactly one request may report first creation, got %d", firstCreators)
266		}
267	
268		// 所有成功返回必须对应同一份保存提案，且成员次序为首次创建者的排列。
269		for i := range results {
270			r := &results[i]
271			if !reflect.DeepEqual(r.resp.Proposal, winnerView) {
272				t.Fatalf("process %d returned a different proposal view:\n%+v\nwant:\n%+v",
273					i, r.resp.Proposal, winnerView)
274			}
275			assertSavedConcProposal(t, r.resp.Proposal, id, wantActions, winnerMemberOrder)
276		}
277	
278		// 全部创建结束后，单项查询只能展示这一个完整的胜出版本。
279		so, se, code := runCLI(t, binary, state, "proposal", "--id", id, "--json")
280		if code != 0 {
281			t.Fatalf("proposal query failed: %s", se)
282		}
283		var saved VoteProposalView
284		if err := json.Unmarshal([]byte(so), &saved); err != nil {
285			t.Fatalf("proposal query output is not JSON: %v\n%s", err, so)
286		}
287		assertSavedConcProposal(t, &saved, id, wantActions, winnerMemberOrder)
288	
289		// 提案列表同样只有一个完整版本。
290		lo, le, code := runCLI(t, binary, state, "proposals", "--json")
291		if code != 0 {
292			t.Fatalf("proposals query failed: %s", le)
293		}
294		var listed []VoteProposalView
295		if err := json.Unmarshal([]byte(lo), &listed); err != nil {
296			t.Fatalf("proposals output is not JSON: %v\n%s", err, lo)
297		}
298		if len(listed) != 1 || listed[0].ID != id ||
299			!reflect.DeepEqual(listed[0].Actions, wantActions) || listed[0].State != "voting" {
300			t.Fatalf("proposal list must contain exactly one voting winner, got %+v", listed)
301		}
302	
303		// 仍在投票、票据为空、无计票结论；资金库余额、账户余额与执行凭据不变。
304		assertNoTreasuryChange(t, binary, state, 1000)
305	}
306	
307	// TestCrossProcessConcurrentCreateVoteActionOrderConflict：两组请求使用相同
308	// 成员与治理规则，仅动作次序不同（先 100 后 50 vs 先 50 后 100；合计金额与
309	// 最终收款账户相同，仍是不同的提案定义）。任意一组都可能成为首次成功方：
310	// 与保存版本相同的请求全部成功（恰好一个首次创建，其余确认已有提案），
311	// 另一组全部以现有的内容冲突失败——退出码 1、原因写入 stderr、stdout 不输出
312	// 成功创建结果，冲突不得被包装成成功重试。
313	func TestCrossProcessConcurrentCreateVoteActionOrderConflict(t *testing.T) {
314		binary := buildCLI(t)
315		state := filepath.Join(t.TempDir(), "treasury.json")
316		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
317			t.Fatal("init failed")
318		}
319	
320		const id = "gip-conc-conflict"
321		actionsA := []string{"transfer:audits:100", "transfer:audits:50"}
322		actionsB := []string{"transfer:audits:50", "transfer:audits:100"}
323		const perGroup = 8
324		n := perGroup * 2
325		actionsFor := func(i int) []string {
326			if i < perGroup {
327				return actionsA
328			}
329			return actionsB
330		}
331		results := runConcurrentCreates(t, binary, state, id, n, actionsFor)
332		for i := range results {
333			if i < perGroup {
334				results[i].group = "A"
335			} else {
336				results[i].group = "B"
337			}
338		}
339	
340		creatorIdx := -1
341		for i := range results {
342			r := &results[i]
343			if r.code != 0 {
344				continue // 冲突结果稍后逐类核对
345			}
346			r.resp = &createVoteCLIResponse{}
347			if err := json.Unmarshal([]byte(r.stdout), r.resp); err != nil {
348				t.Fatalf("process %d success output is not JSON: %v\n%s", i, err, r.stdout)
349			}
350			if r.resp.Proposal == nil {
351				t.Fatalf("process %d success output missing proposal object: %s", i, r.stdout)
352			}
353			if !r.resp.Existed {
354				if creatorIdx != -1 {
355					t.Fatalf("multiple requests (%d and %d) both claim first creation", creatorIdx, i)
356				}
357				creatorIdx = i
358			}
359		}
360		if creatorIdx == -1 {
361			t.Fatal("exactly one request must create the proposal first, none succeeded")
362		}
363		winnerGroup := results[creatorIdx].group
364		wantActions := actionsFor(creatorIdx)
365	
366		successes, conflicts := 0, 0
367		for i := range results {
368			r := &results[i]
369			if r.group == winnerGroup {
370				// 与保存版本相同：全部成功，除首次创建者外都必须是 already_exists。
371				if r.code != 0 {
372					t.Fatalf("process %d in winning group %s must succeed: exit=%d stderr=%s",
373						i, r.group, r.code, r.stderr)
374				}
375				if i == creatorIdx {
376					if r.resp.Existed {
377						t.Fatalf("creator process %d must report first creation, got already_exists", i)
378					}
379				} else if !r.resp.Existed {
380					t.Fatalf("process %d must confirm the existing proposal (already_exists=true)", i)
381				}
382				if !reflect.DeepEqual(r.resp.Proposal, results[creatorIdx].resp.Proposal) {
383					t.Fatalf("process %d returned a different proposal than the saved winner", i)
384				}
385				assertSavedConcProposal(t, r.resp.Proposal, id, wantActions, nil)
386				successes++
387			} else {
388				// 内容冲突：域错误退出码 1，原因写 stderr，stdout 不输出成功结果。
389				if r.code != 1 {
390					t.Fatalf("conflicting process %d exit=%d, want 1 (stdout=%s stderr=%s)",
391						i, r.code, r.stdout, r.stderr)
392				}
393				if strings.TrimSpace(r.stdout) != "" {
394					t.Fatalf("conflict must not print a success result on stdout, got %q", r.stdout)
395				}
396				if strings.Contains(r.stdout, "already_exists") {
397					t.Fatalf("conflict must not be wrapped as a successful retry: %q", r.stdout)
398				}
399				if !strings.Contains(r.stderr, "different timelock or actions") ||
400					!strings.Contains(r.stderr, id) {
401					t.Fatalf("conflict stderr must name the content conflict and proposal, got %q", r.stderr)
402				}
403				conflicts++
404			}
405		}
406		if successes != perGroup {
407			t.Fatalf("winning group successes=%d, want all %d", successes, perGroup)
408		}
409		if conflicts != perGroup {
410			t.Fatalf("losing group conflicts=%d, want all %d", conflicts, perGroup)
411		}
412	
413		// 全部创建结束后：单项查询与列表都只展示一个完整胜出版本，动作原文与
414		// 次序一致；仍在投票、票据为空、无计票结论，资金与凭据保持创建前的值。
415		so, se, code := runCLI(t, binary, state, "proposal", "--id", id, "--json")
416		if code != 0 {
417			t.Fatalf("proposal query failed: %s", se)
418		}
419		var saved VoteProposalView
420		if err := json.Unmarshal([]byte(so), &saved); err != nil {
421			t.Fatalf("proposal query output is not JSON: %v\n%s", err, so)
422		}
423		assertSavedConcProposal(t, &saved, id, wantActions, nil)
424		if saved.Actions[0] != wantActions[0] || saved.Actions[1] != wantActions[1] {
425			t.Fatalf("saved action text/order=%v, want %v", saved.Actions, wantActions)
426		}
427	
428		lo, le, code := runCLI(t, binary, state, "proposals", "--json")
429		if code != 0 {
430			t.Fatalf("proposals query failed: %s", le)
431		}
432		var listed []VoteProposalView
433		if err := json.Unmarshal([]byte(lo), &listed); err != nil {
434			t.Fatalf("proposals output is not JSON: %v\n%s", err, lo)
435		}
436		if len(listed) != 1 || listed[0].ID != id ||
437			!reflect.DeepEqual(listed[0].Actions, wantActions) || listed[0].State != "voting" {
438			t.Fatalf("proposal list must contain exactly one winner with its original action order, got %+v", listed)
439		}
440	
441		assertNoTreasuryChange(t, binary, state, 1000)
442	}
443

