1100		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
1101			t.Fatal("init failed")
1102		}
1103		register := []string{"register", "--id", "gip-1", "--timelock", "100",
1104			"--action", "transfer:audits:250", "--action", "transfer:legal:5", "--json"}
1105	
1106		type registerResponse struct {
1107			ID                string   `json:"id"`
1108			State             string   `json:"state"`
1109			TimelockEnd       int64    `json:"timelock_end"`
1110			Actions           []string `json:"actions"`
