1147		if so, se, code := runCLI(t, binary, state, "register", "--id", "gip-1", "--timelock", "100",
1148			"--action", "transfer:audits:250", "--action", "transfer:legal:5"); code != 0 ||
1149			!strings.Contains(so, "already registered") || !strings.Contains(so, "state=executed") {
1150			t.Fatalf("text retry after execute exit=%d so=%s se=%s", code, so, se)
1151		}
1152	
1153		// 已执行提案的内容冲突（时间锁、动作原文、动作顺序）仍然失败，不返回成功对象。
1154		if so, se, code := runCLI(t, binary, state, "register", "--id", "gip-1", "--timelock", "101",
1155			"--action", "transfer:audits:250", "--action", "transfer:legal:5", "--json"); code != 1 ||
